(function(){
  'use strict';
  var KEY='welog-section-layout-v2',controls=document.getElementById('controls'),sheet=document.getElementById('sheet');
  var defs={pair:{label:'페어명',scale:100,x:0,y:0},characters:{label:'A+B 세트',scale:100,x:0,y:0},center:{label:'중앙 그림',scale:100,x:0,y:0},ok:{label:'OK 표시',scale:100,x:0,y:0},credit:{label:'커미션 출처',scale:100,x:0,y:0}};
  function clone(v){return JSON.parse(JSON.stringify(v))}
  function read(){var out=clone(defs);try{var s=JSON.parse(localStorage.getItem(KEY)||'{}');Object.keys(out).forEach(function(k){if(!s[k])return;out[k].scale=Math.max(60,Math.min(150,Number(s[k].scale)||100));out[k].x=Math.max(-260,Math.min(260,Number(s[k].x)||0));out[k].y=Math.max(-260,Math.min(260,Number(s[k].y)||0))})}catch(e){}return out}
  function write(v){try{localStorage.setItem(KEY,JSON.stringify(v))}catch(e){}}
  function ensureFooterZones(root){if(!root)return;var block=root.querySelector('.sheet-commission-footer .commission-block');if(!block)return;var ok=block.querySelector('.welog-ok-zone');if(!ok){var raw=Array.from(block.children).find(function(el){return el.tagName==='DIV'&&!el.classList.contains('welog-credit-zone')});if(raw){raw.classList.add('welog-ok-zone');ok=raw}}
    var credit=block.querySelector('.welog-credit-zone');if(!credit){credit=document.createElement('div');credit.className='welog-credit-zone';var small=Array.from(block.children).find(function(el){return el.tagName==='SMALL'}),b=Array.from(block.children).find(function(el){return el.tagName==='B'});if(small)credit.appendChild(small);if(b)credit.appendChild(b);block.appendChild(credit)}
  }
  function targets(root){ensureFooterZones(root);return{pair:[root.querySelector('.pair-title-display')].filter(Boolean),characters:[root.querySelector('.profile.left'),root.querySelector('.profile.right')].filter(Boolean),center:[root.querySelector('.center')].filter(Boolean),ok:[root.querySelector('.welog-ok-zone')].filter(Boolean),credit:[root.querySelector('.welog-credit-zone')].filter(Boolean)}}
  function applyTo(root){if(!root)return;var state=read(),map=targets(root);Object.keys(map).forEach(function(k){var s=state[k],t='translate('+s.x+'px,'+s.y+'px) scale('+(s.scale/100)+')';map[k].forEach(function(el){el.style.setProperty('transform',t,'important');el.style.setProperty('transform-origin','center center','important')})});if(root===sheet)requestAnimationFrame(autoFit)}
  function autoFit(){if(!sheet)return;sheet.style.setProperty('--welog-safe-x','0px');sheet.style.setProperty('--welog-safe-top','0px');sheet.style.setProperty('--welog-safe-bottom','0px');requestAnimationFrame(function(){var sr=sheet.getBoundingClientRect(),map=targets(sheet),rects=[];Object.keys(map).forEach(function(k){map[k].forEach(function(el){var r=el.getBoundingClientRect();if(r.width&&r.height)rects.push(r)})});if(!rects.length)return;var left=Math.min.apply(null,rects.map(function(r){return r.left})),right=Math.max.apply(null,rects.map(function(r){return r.right})),top=Math.min.apply(null,rects.map(function(r){return r.top})),bottom=Math.max.apply(null,rects.map(function(r){return r.bottom}));var sx=Math.max(0,Math.ceil(Math.max(sr.left-left,right-sr.right))+8),st=Math.max(0,Math.ceil(sr.top-top)+8),sb=Math.max(0,Math.ceil(bottom-sr.bottom)+8);sheet.style.setProperty('--welog-safe-x',sx+'px');sheet.style.setProperty('--welog-safe-top',st+'px');sheet.style.setProperty('--welog-safe-bottom',sb+'px')})}
  function row(k,d){return'<div class="welog-section-row" data-section-row="'+k+'"><strong>'+d.label+'</strong><label><span>크기</span><input type="range" min="60" max="150" step="1" data-section-scale="'+k+'"><b data-section-scale-v="'+k+'"></b></label><label><span>가로</span><input type="range" min="-260" max="260" step="5" data-section-x="'+k+'"><b data-section-x-v="'+k+'"></b></label><label><span>세로</span><input type="range" min="-260" max="260" step="5" data-section-y="'+k+'"><b data-section-y-v="'+k+'"></b></label></div>'}
  function ensureControls(){if(!controls)return;var anchor=controls.querySelector('.welog-spacing-control')||controls.querySelector('.layout-ratio-controls');if(!anchor)return;var box=controls.querySelector('.welog-section-layout-control');if(!box){box=document.createElement('section');box.className='welog-section-layout-control';box.innerHTML='<div class="welog-section-layout-head"><b>구역별 위치 · 크기</b><span>각 세트를 따로 조절해도 카드 중앙 정렬은 자동 유지됩니다.</span></div>'+Object.keys(defs).map(function(k){return row(k,defs[k])}).join('');anchor.insertAdjacentElement('afterend',box)}var s=read();Object.keys(s).forEach(function(k){var a=box.querySelector('[data-section-scale="'+k+'"]'),x=box.querySelector('[data-section-x="'+k+'"]'),y=box.querySelector('[data-section-y="'+k+'"]');if(!a)return;a.value=s[k].scale;x.value=s[k].x;y.value=s[k].y;box.querySelector('[data-section-scale-v="'+k+'"]').textContent=s[k].scale+'%';box.querySelector('[data-section-x-v="'+k+'"]').textContent=(s[k].x>0?'+':'')+s[k].x+'px';box.querySelector('[data-section-y-v="'+k+'"]').textContent=(s[k].y>0?'+':'')+s[k].y+'px'})}
  function update(k,prop,v){var s=read();s[k][prop]=Number(v);write(s);ensureControls();applyTo(sheet)}
  if(controls){controls.addEventListener('input',function(e){var k;if((k=e.target.dataset.sectionScale)){update(k,'scale',e.target.value);return}if((k=e.target.dataset.sectionX)){update(k,'x',e.target.value);return}if((k=e.target.dataset.sectionY)){update(k,'y',e.target.value);return}},true)}
  function refresh(){ensureControls();applyTo(sheet);document.querySelectorAll('.welog-exact-preview-sheet').forEach(applyTo)}
  var pending=false;function schedule(){if(pending)return;pending=true;setTimeout(function(){pending=false;refresh()},0)}
  if(controls)new MutationObserver(schedule).observe(controls,{childList:true,subtree:false});if(sheet)new MutationObserver(schedule).observe(sheet,{childList:true,subtree:true});
  document.addEventListener('click',function(){setTimeout(refresh,0)},true);window.addEventListener('resize',function(){setTimeout(function(){applyTo(sheet)},0)});setTimeout(refresh,0);
})();